(function(){for(var path=location.pathname.replace(/\/+$/,"")||"/",APP=["/dashboard","/squad-analysis"],inApp=!1,i=0;i<APP.length;i++)if(path===APP[i]||path.indexOf(APP[i]+"/")===0){inApp=!0;break}if(inApp){var OPEN=["/dashboard/login","/dashboard/scouts-desk","/dashboard/news"];if(OPEN.indexOf(path)===-1){var id=null;try{id=localStorage.getItem("fpl_team_id")}catch{}if(!id){var next=path+location.search+location.hash;location.replace("/dashboard/login?next="+encodeURIComponent(next))}}}})();
